def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        col_values = [r[i] for r in rows]
        numeric_values = []
        for v in col_values:
            try:
                # Convert to float if possible
                num = float(v)
                numeric_values.append(num)
            except (ValueError, TypeError):
                # If not numeric, skip
                pass
        if numeric_values:
            total = sum(numeric_values)
            # If total is integer, return as int
            if total.is_integer():
                result.append(int(total))
            else:
                result.append(total)
        else:
            result.append("")
    return result

